"""Self-contained local web console served by the FSDR API."""

DASHBOARD_HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>OCI OpenSearch FSDR</title>
<style>
:root{color-scheme:dark;--bg:#070e0a;--panel:#0b1610;--line:#6ad9e6;--cyan:#5eeeff;--green:#55f080;--yellow:#f4f342;--magenta:#f184ff;--red:#ff7885;--muted:#b4c7bd}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:#d5e3da;font:14px ui-monospace,SFMono-Regular,Menlo,monospace}header{margin:12px 20px 0;padding:10px 14px;border:1px solid var(--line);display:flex;justify-content:space-between;gap:16px;align-items:center}h1{font-size:18px;color:var(--cyan);margin:0}.sub{color:var(--muted);margin-top:5px}main{padding:16px 20px;display:grid;gap:16px}.login{display:flex;gap:9px;align-items:center}.login input{min-width:310px}button,input{font:inherit;border:1px solid var(--line);border-radius:0;padding:8px;background:#07100a;color:#e9f1e9}button{cursor:pointer;color:var(--cyan)}.hidden{display:none}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.panel{border:1px solid var(--line);background:rgba(10,23,15,.96);padding:13px;min-width:0}.panel h2{margin:0 0 10px;font-size:15px;color:var(--cyan)}.cluster-a h2{color:var(--yellow)}.cluster-b h2{color:var(--magenta)}.metric{font-size:21px;color:var(--green);float:right}.details{color:var(--muted);margin:8px 0}table{border-collapse:collapse;width:100%}th{text-align:left;color:var(--cyan);font-weight:normal;border-bottom:1px solid #2b676c}td,th{padding:6px 4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:260px}.number{text-align:right;color:var(--green)}.status{color:var(--green)}.warn{color:var(--yellow)}.error{color:var(--red)}#console{height:330px;overflow:auto;white-space:pre-wrap;background:#050a07;padding:12px;border:1px solid var(--line);color:#a8f5bc}.job{cursor:pointer}.selected{background:#173427}.footer{color:var(--cyan);text-align:right}.banner{color:var(--yellow)}@media(max-width:900px){.grid{grid-template-columns:1fr}.login input{min-width:0;width:100%}}
</style></head><body>
<header><div><h1>OCI OpenSearch FSDR</h1><div class="sub">Local HTTPS console · read-only cluster observer · serialized DR jobs</div></div><div class="login"><input id="token" type="password" placeholder="Bearer token"><button onclick="connect()">Connect</button><button onclick="forget()">Forget</button></div></header>
<main><div id="notice" class="banner">Enter the local Bearer token to load the dashboard.</div><section id="dash" class="hidden"><div id="overview" class="panel"></div><div id="clusters" class="grid"></div><div class="panel"><h2>API jobs</h2><table><thead><tr><th>ID</th><th>Command</th><th>Status</th><th>Submitted</th><th>Finished</th></tr></thead><tbody id="jobs"></tbody></table></div><div class="panel"><h2>Selected job console</h2><pre id="console">Select a job to view the captured FSDR output.</pre></div><div class="footer" id="clock"></div></section></main>
<script>
let token=sessionStorage.getItem('fsdr-token')||'',selected='';document.querySelector('#token').value=token;
const esc=s=>String(s??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path){let r=await fetch(path,{headers:{Authorization:'Bearer '+token}});if(!r.ok)throw new Error(r.status===401?'Authentication failed':await r.text());return r;}
function connect(){token=document.querySelector('#token').value.trim();sessionStorage.setItem('fsdr-token',token);refresh();}function forget(){sessionStorage.removeItem('fsdr-token');token='';location.reload();}
function cluster(v,key){let rows=v.indices.map(i=>`<tr><td>${esc(i.index)}</td><td class="number">${esc(i.documents)}</td><td class="${i.error?'error':'status'}">${esc(i.error||i.replication?.status)}</td><td class="number">${i.replication?.leader_checkpoint!=null?esc(i.replication.leader_checkpoint)+' / '+esc(i.replication.follower_checkpoint):''}</td></tr>`).join('');return `<div class="panel cluster-${key}"><h2>${esc(v.name)} (${esc(v.role).toUpperCase()}) <span class="metric">${esc(v.documents)}</span></h2><div class="details">Protected indices: ${v.indices.length} · documents total</div>${v.error?`<div class="error">${esc(v.error)}</div>`:''}<table><thead><tr><th>Index</th><th class="number">Docs</th><th>State</th><th class="number">Leader / follower</th></tr></thead><tbody>${rows||'<tr><td colspan="4">No protected indices observed.</td></tr>'}</tbody></table></div>`;}
async function output(id){if(!id)return;try{document.querySelector('#console').textContent=await (await api('/v1/jobs/'+id+'/output')).text()}catch(e){document.querySelector('#console').textContent=e.message}}
async function refresh(){if(!token)return;try{let [mon,jobs]=await Promise.all([(await api('/v1/monitor')).json(),(await api('/v1/jobs')).json()]);document.querySelector('#dash').classList.remove('hidden');document.querySelector('#notice').textContent=(mon.errors||[]).join(' ')||'Observer refreshed without changing cluster state.';document.querySelector('#overview').innerHTML=`<h2>FSDR state</h2><div>Phase: <b>${esc(mon.phase)}</b> · primary: <b>${esc(mon.primary)}</b> · protected indices: <b>${mon.indices.length}</b></div>`;document.querySelector('#clusters').innerHTML=['a','b'].map(k=>mon.clusters[k]?cluster(mon.clusters[k],k):'').join('');if(!selected&&jobs.jobs[0])selected=jobs.jobs[0].id;document.querySelector('#jobs').innerHTML=jobs.jobs.map(j=>`<tr class="job ${j.id===selected?'selected':''}" onclick="selected='${j.id}';output(selected);refresh()"><td>${esc(j.id.slice(0,12))}</td><td>${esc(j.request.command)}</td><td class="${j.status==='failed'?'error':j.status==='succeeded'?'status':'warn'}">${esc(j.status)}</td><td>${esc(j.submitted_at)}</td><td>${esc(j.finished_at)}</td></tr>`).join('');if(selected)output(selected);document.querySelector('#clock').textContent='Last refresh: '+new Date().toLocaleString();}catch(e){document.querySelector('#notice').textContent=e.message;document.querySelector('#dash').classList.add('hidden');}}
refresh();setInterval(refresh,5000);
</script></body></html>'''
